#include <stdio.h>
int m(int x){x%=26;return x<0?x+26:x;}int inv(int x){for(int i=1;i<26;i++)if(x*i%26==1)return i;return -1;}
int main(){int P[2][2],C[2][2],K[2][2],d,di;puts("Enter plaintext matrix P (4 integers, row-wise):");for(int i=0;i<2;i++)for(int j=0;j<2;j++)scanf("%d",&P[i][j]);puts("Enter matching ciphertext matrix C (4 integers, row-wise):");for(int i=0;i<2;i++)for(int j=0;j<2;j++)scanf("%d",&C[i][j]);d=m(P[0][0]*P[1][1]-P[0][1]*P[1][0]);di=inv(d);if(di<0){puts("P is not invertible modulo 26.");return 1;}int I[2][2]={{m(P[1][1]*di),m(-P[0][1]*di)},{m(-P[1][0]*di),m(P[0][0]*di)}};for(int i=0;i<2;i++)for(int j=0;j<2;j++){K[i][j]=0;for(int t=0;t<2;t++)K[i][j]=m(K[i][j]+C[i][t]*I[t][j]);}puts("Recovered key matrix:");for(int i=0;i<2;i++)printf("%d %d\\n",K[i][0],K[i][1]);return 0;}
